    async fn core_stream_transport_async(
        request: SdkRequest,
        _auth: AuthResolved,
        timeout: Duration,
    ) -> Result<SdkByteStream, SdkError> {
        let client = reqwest::Client::builder()
            .timeout(timeout)
            .build()
            .map_err(|e| {
                SdkError::Network(SdkNetworkError {
                    message: format!("reqwest client: {}", e),
                    request_id: None,
                })
            })?;
        let method = reqwest::Method::from_bytes(request.method.as_bytes()).map_err(|e| {
            SdkError::Network(SdkNetworkError {
                message: format!("invalid method: {}", e),
                request_id: None,
            })
        })?;
        // `request.url` already carries the query (see `append_query`).
        let mut builder = client.request(method, &request.url);
        for (k, v) in &request.headers {
            builder = builder.header(k, v);
        }
        if let Some(bytes) = &request.body_bytes {
            builder = builder.body(bytes.clone());
        } else if let Some(body) = &request.body {
            builder = builder.body(encode_structured_body(&request.content_type, body));
        }
        let response = match builder.send().await {
            Ok(r) => r,
            Err(e) if e.is_timeout() => {
                return Err(SdkError::Timeout(SdkTimeoutError {
                    elapsed: timeout,
                    request_id: None,
                }))
            }
            Err(e) => {
                return Err(SdkError::Network(SdkNetworkError {
                    message: e.to_string(),
                    request_id: None,
                }))
            }
        };
        let status_code = response.status().as_u16();
        let mut headers = HashMap::new();
        for (k, v) in response.headers() {
            if let Ok(s) = v.to_str() {
                headers.insert(k.as_str().to_ascii_lowercase(), s.to_string());
            }
        }
        let request_id = find_request_id(&headers);
        if !(200..300).contains(&status_code) {
            let status_text = response
                .status()
                .canonical_reason()
                .unwrap_or("")
                .to_string();
            let body = response.bytes().await.map_err(|e| {
                SdkError::Network(SdkNetworkError {
                    message: format!("read error response: {}", e),
                    request_id: request_id.clone(),
                })
            })?;
            return Err(SdkError::Http(Box::new(SdkHttpError {
                data: None,
                status_code,
                status_text,
                body: body.to_vec(),
                headers,
                request_id,
            })));
        }
        let wants_events = request
            .headers
            .get("Accept")
            .is_some_and(|accept| accept == "text/event-stream");
        if let Some(content_type) = json_answer(&headers).filter(|_| wants_events) {
            let body = response.bytes().await.map_err(|e| {
                SdkError::Network(SdkNetworkError {
                    message: format!("read response: {}", e),
                    request_id: request_id.clone(),
                })
            })?;
            return Err(response_decode_error(
                status_code,
                &headers,
                request_id,
                &body,
                None,
                format!("expected an event stream, received {content_type}"),
            ));
        }
        // `chunk` yields whatever has arrived, so events surface before the
        // response completes — the whole point of the streaming surface.
        Ok(Box::pin(futures::stream::unfold(
            Some(response),
            move |state| {
                let request_id = request_id.clone();
                async move {
                    let mut response = state?;
                    match response.chunk().await {
                        Ok(Some(chunk)) => Some((Ok(chunk.to_vec()), Some(response))),
                        Ok(None) => None,
                        Err(e) => Some((
                            Err(SdkError::Network(SdkNetworkError {
                                message: format!("stream read: {}", e),
                                request_id,
                            })),
                            None,
                        )),
                    }
                }
            },
        )))
    }

    /// Async mirror of `wait_for` — polls a long-running operation until terminal.
    pub async fn wait_for_async<T, F, Fut, G>(
        mut poll: F,
        is_terminal: G,
        config: super::WaitForConfig,
    ) -> Result<T, SdkError>
    where
        F: FnMut() -> Fut,
        Fut: Future<Output = Result<T, SdkError>>,
        G: Fn(&T) -> super::WaitForTerminal,
    {
        let deadline = Instant::now() + config.timeout;
        let mut interval = config.interval;
        loop {
            let result = poll().await?;
            let state = is_terminal(&result);
            if state.done {
                if state.failed {
                    return Err(SdkError::Network(SdkNetworkError {
                        message: format!(
                            "operation failed: {}",
                            state.reason.unwrap_or_else(|| "unknown".to_string())
                        ),
                        request_id: None,
                    }));
                }
                return Ok(result);
            }
            if Instant::now() >= deadline {
                return Err(SdkError::Timeout(SdkTimeoutError {
                    elapsed: config.timeout,
                    request_id: None,
                }));
            }
            tokio::time::sleep(std::cmp::min(interval, config.max_interval)).await;
            interval = std::cmp::min(interval * 2, config.max_interval);
        }
    }
